        edge_pts = sorted(others, key=lambda p: (p[0] + p[1], p[0], p[1]))[:2]

    # Determine edge row/col and starting points
    er1, ec1 = edge_pts[0]
    er2, ec2 = edge_pts[1]

    hrow = min(er1, er2)
    vcol = min(ec1, ec2)
    hstart = max(ec1, ec2)
    vstart = max(er1, er2)

    out = [[0] * m for _ in range(n)]

    def set_sym(r, c, v):
        for rr in {r, n - 1 - r}:
            for cc in {c, m - 1 - c}:
                out[rr][cc] = v

